const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define region: Northern Siberia east of Taz River (approximate bounds)
  const roi = ee.Geometry.Polygon([
    [78, 66], [78, 72], [180, 72], [180, 66], [78, 66]
  ]);

  // 2. Function to get water mask from Landsat
  function getWaterMask(collection, startDate, endDate) {
    const col = collection
      .filterBounds(roi)
      .filterDate(startDate, endDate);

    // Use median composite
    const image = col.median().clip(roi);

    // Calculate NDWI for water detection
    // For Landsat 5/7: (B2 - B5) / (B2 + B5)
    // For Landsat 1-3 MSS: (B1 - B4) / (B1 + B4) - approximate
    let ndwi;
    if (collection.id().includes('LM0')) {
      // Landsat MSS (1-3)
      ndwi = image.normalizedDifference(['B1', 'B4']);
    } else {
      // Landsat 5/7
      ndwi = image.normalizedDifference(['SR_B2', 'SR_B5']);
    }

    // Water mask: NDWI > 0.2
    return ndwi.gt(0.2).selfMask();
  }

  // 3. Try multiple data sources for each year
  const collections = {
    1973: [
      'LANDSAT/LM03/C02/T1',  // Landsat 3 MSS
      'LANDSAT/LM02/C02/T1',  // Landsat 2 MSS
      'LANDSAT/LM01/C02/T1'   // Landsat 1 MSS
    ],
    2002: [
      'LANDSAT/LE07/C02/T1_L2',  // Landsat 7
      'LANDSAT/LT05/C02/T1_L2'   // Landsat 5
    ]
  };

  let waterMasks = {};
  let validPixels = {};

  // Process each year
  for (const [year, colList] of Object.entries(collections)) {
    let waterMask = null;

    for (const colId of colList) {
      const collection = ee.ImageCollection(colId);
      const startDate = `${year}-06-01`;  // Summer months for open water
      const endDate = `${year}-09-30`;

      // Check collection size
      const count = collection
        .filterBounds(roi)
        .filterDate(startDate, endDate)
        .size();

      if (count.getInfo() > 0) {
        waterMask = getWaterMask(collection, startDate, endDate);
        break;
      }
    }

    if (!waterMask) {
      console.log(`${year}: No images found`);
      console.log('<answer>C1</answer>');
      return;
    }

    // Count water pixels
    const stats = waterMask.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: roi,
      scale: 1000,
      maxPixels: 1e9
    });

    const waterPixels = stats.getNumber('nd').getInfo();
    waterMasks[year] = waterMask;
    validPixels[year] = waterPixels;

    console.log(`${year} water pixels: ${waterPixels}`);
  }

  // 4. Validate data
  if (validPixels[1973] === 0 || validPixels[2002] === 0) {
    console.log('<answer>C2</answer>');
    return;
  }

  // 5. Compare water extent
  const change = validPixels[2002] - validPixels[1973];
  console.log(`Change: ${change.toFixed(0)} pixels`);

  // Check if change is valid number
  if (isNaN(change) || !isFinite(change)) {
    console.log('<answer>C3</answer>');
    return;
  }

  // 6. Final decision
  if (change < 0) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
